'C:\\SAP\\sap-dev-academy\\content\\abap\\CH15\\_chapter.md'
)
foreach ("'$file in $files) {
  Write-Output ('"'###FILE ' + "'$file)
  $lines = Get-Content -LiteralPath $file -Encoding UTF8
  $inside = $false
  for ($i = 0; $i -lt $lines.Count; $i++) {
    if (-not $inside -and $lines[$i] -match '"'"'^```abap'"\\s*"'$'"') { "'$inside = $true; Write-Output ('"'###BLOCK_START ' + ("'$i + 1)); continue }
    if ($inside -and $lines[$i] -match '"'"'^```'"\\s*"'$'"') { "'$inside = $false; Write-Output ('"'###BLOCK_END ' + ("'$i + 1)); continue }
    if ($inside) { Write-Output ((($i + 1).ToString()) + '"': ' + "'$lines[$i]) }
  }
}'

